    if priority is None:
        return default
    if isinstance(priority, bool) or not isinstance(priority, int):
        raise InvalidPriorityError(
            f"priority must be an int in "
            f"[{MIN_TASK_PRIORITY}, {MAX_TASK_PRIORITY}], "
            f"got {priority!r}"
        )
